pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        // The owner is the one who deploys the contract (msg.sender in the constructor).
        // We can't fuzz the owner easily, but the owner is fixed to test contract address.
        // We can fuzz the actor sending ether and then call withdrawAll as owner.
        // Only the owner can call withdrawAll, so the test itself (which is the owner) must call it.
        // The actor can send ether to the contract.
        vm.assume(amount > 0 && amount <= type(uint128).max);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));

        // Give actor some ether
        vm.deal(actor, amount);

        // Actor sends ether to c via receive()
        vm.prank(actor);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "send eth failed");

        // Record balances before withdrawAll
        uint256 ownerBalanceBefore = address(this).balance;
        uint256 contractBalanceBefore = address(c).balance;

        // call withdrawAll as owner (this contract deployed c, so this is owner)
        c.withdrawAll();

        // Record balances after
        uint256 ownerBalanceAfter = address(this).balance;
        uint256 contractBalanceAfter = address(c).balance;

        // The correct behavior: after withdrawAll, the owner's ETH balance should increase by exactly the contract's previous balance.
        // The buggy version withdraws 0, so the owner balance stays same, contract balance stays same.
        // The rule: ownerBalanceAfter == ownerBalanceBefore + contractBalanceBefore.
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + contractBalanceBefore);
    }
}

