pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(0));
        vm.assume(amount > 0);
        vm.assume(target.balance == 0);

        vm.deal(address(c), amount * 2);
        vm.prank(c.owner());
        c.sendMoney(target, amount, "");

        uint256 cBal = address(c).balance;
        // Target is non-payable by assumption, so transfer fails in both.
        // Reference: call{value:_value}("") reverts on failure -> we won't reach here, but to test property
        // we use try-catch for both. Actually, the property is: after a failed send, contract balance must not decrease.
        // We assert that if transfer failed (target balance 0), contract balance must equal amount*2 minus 0.
        // Since target is non-payable, it must have 0 balance after.
        bool ok;
        try c.sendMoney(target, amount, "") {} catch { ok = false; }

        // If it reverted, contract balance unchanged.
        // If it didn't revert and target balance 0, contract balance must be amount*2 (failed, no deduction).
        // Bug: send returns false, doesn't revert, balance deducted to amount*2 - amount = amount.
        assertTrue(target.balance == 0 ? cBal == amount * 2 : true);
    }
}
